//$Id$
var RealTime = {
    realtimeInterval: null,
    timeZone: null,
    pendingRequests: [],
    timeDate: function () {
        var millis = Date.now();
        var sD = moment(millis).subtract(1, 'hours').format('DD-MM-YYYY HH:mm');
        var eD = moment(millis).format('DD-MM-YYYY HH:mm');
        return { sD: sD, eD: eD };
    },
    init: function (isFromHistory) {
        $("#content-tab").html(RealtimeHtml.realtimeHtml.replace(/{OPTINONLY}/g, Templates.optinonlyhtml));
        $("#zarealtimecntain").find("[purpose='loader']").append(ZWAF.HTMLPurifier(ZAUtils.getAllCustomAttributes(Templates.boxLoaderHtml)).sanitize(Templates.boxLoaderHtml));
        LeftPanel.selectModuleOnLoad("developers", ".realhbtn");
        $(document).prop("title", I18N.getLocale("realtime.title") + " - " + appDisplayName + " - " + $zag.APPNAME);
        diffCo = 1;
        isSingleDay = true;
        this.timeZone = moment(ZAUtils.getDateStringFromMillis(), 'DD MMM YYYY, hh:mm A').hour();
        startDate = endDate = moment(todayDate, "DD-MM-YYYY").format('YYYY-MM-DD');
        this.cleanupInvalidFilters();        
        var currentPage = LoadContent.getCurrentpageName();
        if (currentPage === "realtime") {
            this.realTimeTabLoad(isFromHistory);
        }
        RealtimeHtml.bindEvents();
        var urlParams = new URLSearchParams(window.location.search);
        if (urlParams.size > 0) {
            var options = ["brand", "platform", "bundle", "devicetype", "devicemodel", "appversion", "osversion", "country"];
            CommonFilter.checkAndGetRemainingFilter("Realtime", options, function(page) {
                 CommonFilter.handlePageNodeFilter();
            });
        } else {
            if (typeof IndexDb !== 'undefined' && IndexDb.getAllValuesFromDB) {
                IndexDb.getAllValuesFromDB("LocalCacheDB", "userPushFilter", function (filters) {
                    if (filters && Object.keys(filters).length > 0) {
                        var allowedFilters = ["brand", "platform", "bundle", "devicetype", "devicemodel", "appversion", "osversion", "country"];
                        var cleanedFilters = {};
                        for (var key in filters) {
                            if (allowedFilters.includes(key)) {
                                cleanedFilters[key] = filters[key];
                            }
                        }
                        CommonFilter.fixedselectedFilterObj = cleanedFilters;
                        CommonFilter.handlePageNodeFilter();
                    }
                });
            }
        }
    },
    cleanupInvalidFilters: function() {
        var allowedFilters = ["brand", "platform", "bundle", "devicetype", "devicemodel", "appversion", "osversion", "country"];
        var invalidFilters = ["customergroup", "exceptiontype", "exceptiongroup"];

        if (CommonFilter.fixedselectedFilterObj) {
            invalidFilters.forEach(function(filterKey) {
                if (CommonFilter.fixedselectedFilterObj.hasOwnProperty(filterKey)) {
                    delete CommonFilter.fixedselectedFilterObj[filterKey];
                }
            });
        }
    },
    getAjaxConfig: function (type) {
        var filterParam = RealTime.getFilterParam();
        var real = RealTime.timeDate();
        var configs = {
            newCrash: {
                url: `/ac/${zsoid}/${appID}/api/widget/v1/timeline`,
                callType: "GET",
                callback: function (response) {
                    if (response && response.status === 200) {
                        RealTime.handleNewCrash(response);
                    }
                },
                data: {
                    mode: mode, dateRangeIndex: 0, sD: real.sD, eD: real.eD, ...filterParam, minuteGranularity: true
                }
            },
            countCatch: {
                url: `/ac/${zsoid}/${appID}/api/widget/v1/count`,
                callType: "GET",
                callback: function (response) {
                    if (response && response.status === 200) {
                        RealTime.handleCountCatch(response);
                    }
                },
                data: { mode: mode, dateRangeIndex: 0, sD: real.sD, eD: real.eD, ...filterParam, minuteGranularity: true }
            },
            topEventsScreens: {
                url: `/ac/${zsoid}/${appID}/api/widget/v1/topEventsScreens`,
                callType: "GET",
                callback: function (response) {
                    if (response && response.status === 200 && response.result) {
                        if (response.result.topEvents) {
                            RealTime.handleEventScreen(response.result.topEvents, 'event');
                        }
                        if (response.result.topScreens) {
                            RealTime.handleEventScreen(response.result.topScreens, 'screen');
                        }
                    }
                },
                data: { mode: mode, dateRangeIndex: 0, limit: 5, sD: real.sD, eD: real.eD, ...filterParam }
            }
        };
        return configs[type] || null;
    },
    realTimeTabLoad: function (isFromHistory) {
    this.isFromHistory = isFromHistory;
    this.abortPendingRequests();
        ['newCrash', 'countCatch', 'topEventsScreens'].forEach(function (type) {
            var config = RealTime.getAjaxConfig(type);
            if (config) {
                RealTime.makeAjaxCall(config.url, config.callType, config.callback, config.data);
            }
        });

        var filterObj = CommonFilter.getFilterParams();
        var pageURL = '/ac/' + zsoid + '/' + appID + '/' + mode + '/' + 'realtime';
        var paramstr = "";
        var allowedFilters = ["brand", "platform", "bundle", "devicetype", "devicemodel", "appversion", "osversion", "country"];

