private void addOrUpdateJiraAuth(
        long projectId,
        String zsoId,
        String accessToken,
        String refreshToken
) throws Exception {
    Map<String, Object> criteriaCols = new HashMap<>();
    criteriaCols.put(AppticsConstants.ZUID, projectId);
    criteriaCols.put(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
    if (MickeyUtil.isRowExist(
            AppticsConstants.REFRESHTOKEN,
            AppticsConstants.REFRESHTOKENID,
            criteriaCols,
            zsoId
    )) {
        LOGGER.log(Level.INFO, "Jira auth available for project already. Updating configs");

        Criteria updateCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
        updateCriteria = updateCriteria.and(
                new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
        );

        Map<String, Object> updateColWithValue = new HashMap<>();
        updateColWithValue.put(AppticsConstants.REFRESHTOKEN, refreshToken);
        updateColWithValue.put(AppticsConstants.ACCESSTOKEN, accessToken);
        updateColWithValue.put(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());

        DBHandler.updateInRedis(AppticsConstants.REFRESHTOKEN, updateCriteria, updateColWithValue, zsoId);

    } else {
        Row authRow = new Row(AppticsConstants.REFRESHTOKEN);
